/// Public verification API for consciousness copying systems
pub struct ConsciousnessVerificationAPI {
    verifier: ConsciousnessFidelityVerifier,
}

impl ConsciousnessVerificationAPI {
    pub fn new() -> Result<Self, VerificationError> {
        Ok(Self {
            verifier: ConsciousnessFidelityVerifier::new()?,
        })
    }

    /// Verify consciousness copy meets all fidelity requirements
    pub fn verify_copy(&self, original: &ConsciousnessState, copy: &ConsciousnessState) -> Result<bool, VerificationError> {
        let metrics = self.verifier.verify_consciousness_fidelity(original, copy)?;

        // Check all fidelity requirements
        let meets_requirements =
            metrics.overall_fidelity >= 0.95 &&
            metrics.phi_fidelity.phi_preservation_ratio >= self.verifier.verification_targets.phi_preservation &&
            metrics.structural_fidelity.strange_loop_similarity >= self.verifier.verification_targets.strange_loop_integrity &&
            metrics.temporal_fidelity.frequency_correlation >= self.verifier.verification_targets.temporal_correlation &&
            metrics.quantum_fidelity.coherence_preservation >= self.verifier.verification_targets.quantum_coherence &&
            metrics.behavioral_fidelity.response_consistency >= self.verifier.verification_targets.behavioral_consistency;

        Ok(meets_requirements)
    }

    /// Get detailed fidelity report
    pub fn get_fidelity_report(&self, original: &ConsciousnessState, copy: &ConsciousnessState) -> Result<FidelityMetrics, VerificationError> {
        self.verifier.verify_consciousness_fidelity(original, copy)
    }
}

